// ЗГЕНЕРОВАНО scripts/bake-vehicles.mjs — не редагувати руками.
// Формат: Int16-позиції ×32000, нормалізовані в x,y ∈ [-0.5, 0.5], z ∈ [-0.5, 0.5]
